/// A smoke failure is a plumbing problem — the request could not be sent or
/// the client was misconfigured. An API error (a response with a non-success
/// status) or a decode error means the request reached the server and came
/// back, which is what this smoke verifies; the synthetic response body the
/// mock returns is not the SDK's concern.
fn is_smoke_failure(error: &Error) -> bool {
    matches!(
        error,
        Error::Transport(_) | Error::Config(_) | Error::MissingParameter(_)
    )
}
